import { doseToVolume } from "./nexo-core";
import {pendingSelection,withdrawalReason} from "../../app/pending-withdrawals";
import type {Patient} from './types';
import {ageDays,number,normalize,extract} from './engine';
export type Presentation={id:string;label:string;strength:number;unit:'mg/mL'|'mg/comprimido'|'mg/g';reference:string};
export type Medicine={id:string;name:string;route:string;presentations:Presentation[];sources:string[];precautions:string;minDays?:number;renal?:boolean;hepatic?:boolean;pregnancyReview?:boolean;allergyTerms?:string[];offLabel?:string};
const p=(id:string,label:string,strength:number,unit:Presentation['unit'],reference='Apresentação de referência. Confirmar produto, concentração e bula brasileira; comercialização atual não reconferida.'):Presentation=>({id,label,strength,unit,reference});
export const medicines:Record<string,Medicine>={
mupirocin:{id:'mupirocin',name:'Mupirocina',route:'Tópica cutânea',presentations:[p('ointment20','Pomada 20 mg/g (2%) · uso cutâneo',20,'mg/g')],sources:['idsa','rchcell'],precautions:'Para impetigo limitado. Evitar olhos/mucosas; formulação cutânea não equivale à intranasal. Não usar preventivamente em todo eczema. Grandes áreas denudadas e doença renal exigem avaliar veículo de polietilenoglicol.'},
hydrocortisone:{id:'hydrocortisone',name:'Acetato de hidrocortisona',route:'Tópica cutânea',presentations:[p('cream10','Creme 10 mg/g (1%) · uso cutâneo',10,'mg/g','Apresentação documentada no PCDT brasileiro de dermatite atópica, 2025')],sources:['ad'],precautions:'Camada fina; evitar olhos, herpes, rosácea, dermatite perioral e micose não tratada. Face, dobras, fralda e grandes áreas aumentam absorção; não usar oclusão sem indicação. Quantidade depende da área, não do peso. Reavaliar em 7 dias.'},
tacrolimus:{id:'tacrolimus',name:'Tacrolimo',route:'Tópica cutânea',presentations:[p('ointment03','Pomada 0,3 mg/g (0,03%) · uso cutâneo',0.3,'mg/g','PCDT brasileiro de dermatite atópica, 2025'),p('ointment1','Pomada 1 mg/g (0,1%) · uso cutâneo',1,'mg/g','PCDT brasileiro de dermatite atópica, 2025')],minDays:2*365.25,sources:['ad'],pregnancyReview:true,precautions:'Não aplicar em infecção ativa ou sob oclusão. Pode causar ardor inicial. Fotoproteção; separar emoliente no mesmo local por 2 horas. Não usar indefinidamente sem reavaliação.'},
cephalexin:{id:'cephalexin',name:'Cefalexina',route:'Oral',presentations:[p('susp50','Suspensão 250 mg/5 mL (50 mg/mL) · VO',50,'mg/mL'),p('caps500','Cápsula / comprimido 500 mg · VO',500,'mg/comprimido')],minDays:28,renal:true,sources:['rchcell','idsa'],allergyTerms:['cefalexina','cefalosporina','penicilina','amoxicilina','betalactam'],precautions:'Confirmar tipo de reação a penicilinas/cefalosporinas. Não cobre MRSA. Ajuste renal necessário em disfunção. Vigiar alergia e diarreia importante. Agitar suspensão; reconstituir e armazenar conforme fabricante, sem diluição adicional.'},
smtmp:{id:'smtmp',name:'Sulfametoxazol + trimetoprima',route:'Oral',presentations:[p('susp8','Suspensão 200 mg + 40 mg/5 mL · VO (TMP 8 mg/mL)',8,'mg/mL'),p('tab160','Comprimido 800 mg + 160 mg · VO (TMP 160 mg)',160,'mg/comprimido')],minDays:60,renal:true,hepatic:true,pregnancyReview:true,sources:['rchcell','idsa'],allergyTerms:['sulfa','trimetoprima','bactrim'],precautions:'TODOS os cálculos usam o componente trimetoprima (TMP). SMX = 5 × TMP. Não usar isoladamente como cobertura de estreptococo na celulite não purulenta. Avaliar G6PD, potássio, função renal e interações (varfarina, metotrexato, espironolactona/IECA/BRA).'},
cetirizine:{id:'cetirizine',name:'Cetirizina',route:'Oral',presentations:[p('solution1','Solução oral 1 mg/mL · VO',1,'mg/mL'),p('tablet10','Comprimido 10 mg · VO',10,'mg/comprimido')],minDays:2*365.25,renal:true,sources:['urticaria','cetirizineBR'],allergyTerms:['cetirizina','hidroxizina'],precautions:'Preferir solução em crianças. Pode causar sonolência; evitar somar sedativos e outros anti-H1. Na urticária, não substitui adrenalina em anafilaxia. O módulo utiliza doses padrão, sem aumento automático para urticária crônica.',offLabel:'Solução 1 mg/mL para urticária a partir de 2 anos: população e indicação da bula brasileira. Outros usos sintomáticos não são certificados por essa bula. Doses abaixo de 2 anos e escalonamento acima da bula não são aplicados automaticamente.'},
permethrin:{id:'permethrin',name:'Permetrina',route:'Tópica cutânea',presentations:[p('lotion50','Loção 50 mg/mL (5%) · frasco 60 mL · uso cutâneo',50,'mg/mL','Bula brasileira Kaodine / Geolab, versão 12/2025')],minDays:60,sources:['scabies','permethrinLabel'],precautions:'Não confundir 5% (escabiose) com 1% (pediculose). Evitar olhos/mucosas; verificar alergia a piretroides. Lactentes/crianças pequenas podem exigir aplicação em couro cabeludo/pescoço conforme avaliação. Não calcular volume corporal por kg.'},
ivermectin:{id:'ivermectin',name:'Ivermectina',route:'Oral',presentations:[p('tablet6','Comprimido 6 mg · VO',6,'mg/comprimido')],minDays:5*365.25,hepatic:true,pregnancyReview:true,sources:['scabies','ivermectinBR'],allergyTerms:['ivermectina'],precautions:'Faixa adotada da referência brasileira SES-SP/FURP: idade a partir de 5 anos E peso a partir de 15 kg. A regra calcula a dose teórica e não valida fracionamento do comprimido. Conferir esquema/forma de tomada na bula brasileira; CDC e bula podem divergir sobre alimentos.',offLabel:'A referência CDC classifica escabiose como off-label nos EUA; isso não define o status da bula brasileira. Não aplicar este esquema automático abaixo de 5 anos, abaixo de 15 kg ou na gestação. O uso fora dessa faixa exige avaliação específica e não é declarado contraindicação absoluta universal por este módulo.'},
clotrimazole:{id:'clotrimazole',name:'Clotrimazol',route:'Tópica cutânea',presentations:[p('cream10','Creme 10 mg/g (1%) · uso cutâneo',10,'mg/g')],sources:['diaper','tinea'],precautions:'Aplicar na pele limpa e seca; não usar em olhos/mucosas com a formulação cutânea. Tinea capitis/unhas não é tratada adequadamente só com creme. Vigiar irritação; evitar associação fixa com corticoide.'},
miconazole:{id:'miconazole',name:'Miconazol',route:'Tópica cutânea',presentations:[p('cream20','Creme dermatológico 20 mg/g (2%) · bisnaga 28 g · uso cutâneo',20,'mg/g','Bula brasileira Geolab, versão 02/2019, consultada em 11/09/2026')],sources:['diaper','miconazoleLabel'],precautions:'Camada fina sobre pele limpa e seca. Não confundir creme cutâneo, vaginal e gel oral. Evitar olhos; avaliar uso de varfarina, sobretudo em áreas extensas.'},
ketoconazole:{id:'ketoconazole',name:'Cetoconazol',route:'Tópica cutânea',presentations:[p('cream20','Creme 20 mg/g (2%) · uso cutâneo',20,'mg/g')],sources:['seborrheic','versicolor'],precautions:'Uso cutâneo; não extrapolar para cetoconazol oral. Evitar olhos e observar irritação. Para couro cabeludo, escolher formulação própria; o cálculo aqui não se refere a shampoo.'},
terbinafineTopical:{id:'terbinafineTopical',name:'Terbinafina tópica',route:'Tópica cutânea',presentations:[p('cream10','Creme 10 mg/g (1%) · uso cutâneo',10,'mg/g')],minDays:12*365.25,sources:['tinea'],precautions:'Módulo restrito a ≥12 anos até confirmar bula específica. Para dermatófitos; não confundir micose superficial com tinea capitis/onicomicose. Não extrapolar esta formulação para tratamento oral.'},
adapalene:{id:'adapalene',name:'Adapaleno',route:'Tópica cutânea',presentations:[p('gel1','Gel 1 mg/g (0,1%) · uso cutâneo',1,'mg/g')],minDays:12*365.25,pregnancyReview:true,sources:['acne'],precautions:'Evitar na gestação/planejamento. Aplicar pequena quantidade em camada fina sobre a área acneica; evitar mucosas, pele eczematosa e exposição solar sem proteção. Não usar mais produto para acelerar resposta.'},
benzoyl:{id:'benzoyl',name:'Peróxido de benzoíla',route:'Tópica cutânea',presentations:[p('gel25','Gel 25 mg/g (2,5%) · uso cutâneo',25,'mg/g')],minDays:12*365.25,sources:['acne'],precautions:'Pode causar irritação e descolorir tecidos/cabelos. Evitar mucosas e pele ferida. Com antibiótico para acne, reduz seleção de resistência; não somar produtos irritantes indiscriminadamente.'},
acyclovirZoster:{id:'acyclovirZoster',name:'Aciclovir · herpes-zóster localizado em adulto',route:'Oral',presentations:[p('tab200','Comprimido 200 mg · VO',200,'mg/comprimido')],minDays:18*365.25,renal:true,pregnancyReview:true,sources:['zoster','acyclovirLabel'],allergyTerms:['aciclovir','valaciclovir'],precautions:'Esquema específico para zóster adulto localizado. Não usar este regime em herpes neonatal/encefalite ou imunossupressão grave. Ajustar intervalo à função renal; hidratação e vigilância de nefro/neurotoxicidade.'}
};
for(const id of ['cephalexin','smtmp','cetirizine','ivermectin','mupirocin','clotrimazole','ketoconazole','terbinafineTopical','acyclovirZoster']) for(const form of medicines[id].presentations) form.reference='Apresentação documentada no Catálogo Farmacológico A–Z · 555 Medicamentos. Bula comercial atual não reconferida; confirmar produto antes de prescrever.';
medicines.cetirizine.presentations.find(form=>form.id==='solution1')!.reference='Bula brasileira Teuto: dicloridrato de cetirizina 1 mg/mL, solução oral; reaberta em 14/09/2026. Cópia da bula do paciente; disponibilidade comercial atual não confirmada. Fonte específica: cetirizineBR.';
export const selectablePresentations=(medicine:Medicine)=>medicine.presentations.filter(form=>!pendingSelection(medicine.name,"",form.label));
export type DoseResult={blocked:string[];formula:string;dose:string;use:string;duration:string;maximum:string;reverse:string;checks:string[];total:string;amountMg?:number;volumeMl?:number;dailyMg?:number;unitCount?:number};
const fmt=(x:number)=>x.toLocaleString('pt-BR',{maximumFractionDigits:3});
export function calculateMedicine(id:string,p:Patient,presentationId:string,conditionId:string):DoseResult{
 const med=medicines[id],form=med?.presentations.find(x=>x.id===presentationId),age=ageDays(p),weight=number(p.weight);
 const r:DoseResult={blocked:[],formula:'',dose:'',use:'',duration:'',maximum:'',reverse:'',checks:[],total:''};
 if(!med||!form){r.blocked.push('Apresentação inválida.');return r;}
 if(pendingSelection(med.name,'',form.label)){r.blocked.push(withdrawalReason);return r;}
 if(age===null||!p.weight.trim()||!Number.isFinite(weight)||weight<0.3||weight>350){r.blocked.push('Idade e peso válidos são necessários.');return r;}
 if(med.minDays!==undefined&&age<med.minDays)r.blocked.push('Faixa etária fora do esquema automático desta apresentação. Verifique alternativa ou regime pediátrico específico.');
 if(med.renal&&p.comorbidities.includes('Doença renal'))r.blocked.push('É necessário informar função renal/depuração para ajustar este medicamento.');
 if(med.hepatic&&p.comorbidities.includes('Doença hepática'))r.blocked.push('Doença hepática informada: definir gravidade e elegibilidade antes do esquema.');
 if(med.pregnancyReview&&p.pregnancy!=='none'&&age>=8*365.25)r.blocked.push('Confirmar gestação/lactação e elegibilidade antes deste medicamento.');
 const allergies=normalize(p.allergies);
 if(p.allergyStatus==='yes'&&(med.allergyTerms??[normalize(med.name.split(' ')[0])]).some(t=>allergies.includes(t)))r.blocked.push('Alergia potencialmente relacionada. Esclarecer fármaco e reação antes de escolher esta opção.');
 if(id==='ivermectin'&&weight<15)r.blocked.push('Ivermectina: o módulo não calcula administração em peso inferior a 15 kg.');
 if(!['none','yes'].includes(p.allergyStatus))r.blocked.push('Situação de alergias não informada: confirmar antes de individualizar o medicamento.');
 if(p.allergyStatus==='yes'&&!p.allergies.trim())r.blocked.push('Informe qual medicamento causou alergia e o tipo de reação.');
 if(id==='ketoconazole'&&age<12*365.25)r.blocked.push('Este esquema de cetoconazol está restrito a adolescentes/adultos; no lactente, definir tratamento específico e apresentação.');
 if(id==='acyclovirZoster'&&(p.distribution==='generalized'||p.comorbidities.some(v=>['Imunossupressão / transplante','HIV','Neoplasia'].includes(v))))r.blocked.push('Possível zóster disseminado ou imunossupressão: definir gravidade, necessidade de terapia EV e esquema especializado.');
 if(id==='tacrolimus'&&form.strength===1&&age<16*365.25)r.blocked.push('Tacrolimo 0,1%: esquema selecionável apenas a partir de 16 anos. Para 2–15 anos, usar 0,03% quando indicado.');
 if(['hydrocortisone','tacrolimus'].includes(id)){
  const detected=extract(p).detected;
  if(id==='tacrolimus'&&(detected.includes('honey')||detected.includes('pustules')))r.blocked.push('Possível infecção cutânea ativa: tratar/avaliar infecção antes do tacrolimo no local.');
  if(detected.includes('vesicles')&&(detected.includes('pain')||detected.includes('fever')))r.blocked.push('Excluir herpes/infecção ativa antes de aplicar imunomodulador ou corticoide na lesão.');
  if(detected.includes('annular')&&detected.includes('scale'))r.blocked.push('Lesão anular descamativa: excluir dermatofitose antes de corticoide/imunomodulador.');
 }
 if(id==='smtmp'&&/metotrexato|varfarina|espironolactona/i.test(normalize(p.medicines)))r.blocked.push('Interação relevante informada: avaliar alternativa e monitorização antes do sulfametoxazol-trimetoprima.');
 if(r.blocked.length)return r;
 const adult=age>=18*365.25;
 let amount=0,frequency=0,maxDose=0,maxDay=0;
 if(id==='cephalexin'){
  amount=adult?500:Math.min(20*weight,750);frequency=adult?4:3;maxDose=adult?1000:750;maxDay=adult?4000:2250;
  r.formula=adult?'Adulto: 500 mg/dose, 6/6 h.':'20 mg/kg/dose × '+fmt(weight)+' kg; limitar a 750 mg/dose. Regime pediátrico RCH.';
  r.use='VO a cada '+(adult?'6':'8')+' horas. Suspensão: agitar e medir com seringa oral.';
  r.duration=conditionId==='impetigo'?'7 dias para impetigo extenso/ectima (IDSA); RCH adota 5 dias para impetigo. Reavaliar 48–72h.':'5 dias inicialmente; reavaliar 24–48h e prolongar se resposta insuficiente.';
 }
 if(id==='smtmp'){
  amount=adult?160:Math.min(4*weight,160);frequency=2;maxDose=160;maxDay=320;
  r.formula='4 mg de TMP/kg/dose × '+fmt(weight)+' kg, máximo 160 mg TMP/dose (adulto: 160 mg).';
  r.use='VO 12/12 h. Dose expressa por TMP; por dose, SMX = '+fmt(amount*5)+' mg.';
  r.duration=conditionId==='impetigo'?'7 dias se indicado para impetigo por MRSA (IDSA).':'5 dias inicialmente; ajustar a evolução/cultura, especialmente após drenagem.';
 }
 if(id==='cetirizine'){
  amount=age<6*365.25?2.5:age<12*365.25?5:10;frequency=age<12*365.25?2:1;maxDose=amount;maxDay=amount*frequency;
  r.formula='Dose por faixa etária: '+fmt(amount)+' mg/dose, '+frequency+' vez(es)/dia; não é dose ponderal.';
  r.use='VO '+(frequency===2?'12/12 h':'a cada 24 h')+'. Não associar outros anti-H1 automaticamente.';
  r.duration='Enquanto houver sintomas, com reavaliação em 3–7 dias; urticária >6 semanas requer plano de doença crônica.';
 }
 if(id==='ivermectin'){
  amount=weight*0.2;frequency=1;maxDose=amount;maxDay=amount;
  r.formula='200 mcg/kg = 0,2 mg/kg; '+fmt(weight)+' kg × 0,2 = '+fmt(amount)+' mg/dose.';
  r.use='VO; 2 doses com intervalo de 7–14 dias. Quantidade em comprimidos abaixo é teórica: validar arredondamento e possibilidade de fracionamento pela bula/farmácia.';
  r.duration='Duas administrações para escabiose comum; não usar este esquema isolado em escabiose crostosa.';
 }
 if(id==='acyclovirZoster'){
  amount=800;frequency=5;maxDose=800;maxDay=4000;r.formula='Adulto: 800 mg/dose, 5 doses/dia.';
  r.use='VO em intervalos de aproximadamente 4 horas durante a vigília, omitindo a dose da madrugada. Ex.: 06h, 10h, 14h, 18h, 22h.';
  r.duration='7 dias; iniciar precocemente, idealmente até 72h. Persistência de novas lesões exige reavaliação.';
 }
 if(amount){
  r.amountMg=amount;r.dailyMg=amount*frequency;
  r.maximum=id==='ivermectin'?'Dose ponderal de 200 mcg/kg por administração; não há teto absoluto universal nesta referência.':fmt(maxDose)+' mg/dose e '+fmt(maxDay)+' mg/dia'+(id==='smtmp'?' de TMP':'')+' neste esquema.';
  if(form.unit==='mg/mL'){
   const exact=doseToVolume(amount,form.strength);
   if(exact===null){r.blocked.push("Concentração ou volume inválido.");return r;}
   const rounded=Math.floor((exact+1e-9)*100)/100;
   const actual=rounded*form.strength;r.volumeMl=rounded;
   r.dose=fmt(amount)+' mg = '+fmt(exact)+' mL/dose. Referência a 0,01 mL: '+fmt(rounded)+' mL/dose; confirmar graduação da seringa.';
   r.reverse=fmt(rounded)+' mL × '+fmt(form.strength)+' mg/mL = '+fmt(actual)+' mg; ÷ '+fmt(weight)+' kg = '+fmt(actual/weight)+' mg/kg/dose; '+fmt(actual*frequency)+' mg/dia.';
   r.total=fmt(rounded*frequency)+' mL/dia. A graduação da seringa deve permitir medir o volume; não arredondar para cima além dos limites.';
   r.checks=['Regra clínica referenciada: faixa, unidade ativa e teto aplicados; confirmar bula do produto.','Matemática: dose total ÷ concentração = volume; referência truncada a 0,01 mL.','Reversa: volume × concentração, dose por kg e total diário recalculados.'];
   if(Math.abs(actual-amount)/amount>0.03)r.blocked.push('Arredondamento excede 3%; esta concentração precisa de outra estratégia de medição.');
  }else{
   const count=amount/form.strength;const displayedCount=Math.round(count*1000)/1000;r.unitCount=count;
   r.dose=fmt(amount)+' mg/dose ≈ '+fmt(displayedCount)+' unidade(s) de '+fmt(form.strength)+' mg (equivalência teórica, não valida fracionamento).';
   r.reverse=fmt(displayedCount)+' × '+fmt(form.strength)+' mg = '+fmt(displayedCount*form.strength)+' mg; ÷ '+fmt(weight)+' kg = '+fmt(displayedCount*form.strength/weight)+' mg/kg/dose (equivalência arredondada).';
   r.total=fmt(amount*frequency)+' mg/dia nos dias de administração.';
   r.checks=['Regra clínica e teto do regime aplicados.','Dose total e equivalência por unidade calculadas.','Dose ponderal e total diário reconstruídos.'];
   if(!Number.isInteger(count))r.use+=' A dose exige fração de unidade: não abrir cápsula nem fracionar comprimido sem validação. Preferir líquido quando disponível.';
  }
  if(id!=='ivermectin'&&(amount>maxDose||amount*frequency>maxDay))r.blocked.push('Dose acima do limite.');
  return r;
 }
 r.formula='Uso tópico: concentração '+fmt(form.strength)+' '+form.unit+'. Quantidade depende da superfície tratada; não existe conversão universal em mg/kg ou mL/kg.';
 r.maximum='Menor quantidade que cubra a área indicada em camada fina. Não foi definido teto universal por kg para esta aplicação.';
 r.reverse='Concentração da apresentação conferida. Quantidade total em gramas/mL não calculada porque a área de aplicação não foi informada.';
 r.checks=['Faixa etária e apresentação verificadas para o esquema exibido.','Concentração preservada; sem transformar percentual em dose ponderal.','Área e quantidade por aplicação precisam de revisão clínica.'];
 const topical:Record<string,[string,string]>={
 mupirocin:['Aplicar pequena quantidade na área acometida 2 vezes/dia (regime IDSA).','5 dias; RCH recomenda 3 vezes/dia. Não misturar frequências; reavaliar em 48–72h se sem resposta.'],
 hydrocortisone:['Aplicar camada fina 2 vezes/dia nas áreas eczematosas indicadas.','Curso inicial curto de 5–7 dias, reavaliando; reduzir/suspender quando controlar. Não ultrapassar 3 semanas em menores de 4 anos (PCDT).'],
 tacrolimus:[form.strength===0.3?'Pomada 0,03%: camada fina 2 vezes/dia até 3 semanas; depois reduzir para 1 vez/dia até controle.':'Pomada 0,1%: camada fina 2 vezes/dia até controle; reavaliar resposta.','Reavaliar em 2–3 semanas. Manutenção de dermatite atópica: 2 aplicações semanais em dias não consecutivos, somente se indicada.'],
 permethrin:['Aplicar no corpo, incluindo dobras, entre dedos, região subungueal e plantas; lavar após 8–14h. Em crianças pequenas, avaliar cabeça/pescoço, evitando olhos e boca.','Repetir aproximadamente no 7º dia. Reaplicar nas mãos se lavadas durante o período de contato.'],
 clotrimazole:['Aplicar camada fina 2 vezes/dia; na tinea, incluir pequena margem ao redor.','Tinea corporis/cruris: usualmente 2–4 semanas; candidíase localizada: reavaliar em 7–14 dias e continuar conforme resolução clínica.'],
 miconazole:['Aplicar camada fina 2 vezes/dia.','Reavaliar em 7–14 dias; bula descreve 2–5 semanas e continuação por 1 semana após desaparecerem os sinais/sintomas.'],
 ketoconazole:['Aplicar camada fina 1 vez/dia nas lesões.','Pitiríase versicolor: 2–3 semanas; dermatite seborreica: 2–4 semanas, com reavaliação.'],
 terbinafineTopical:['Aplicar camada fina 1 vez/dia em dermatofitose cutânea localizada.','1–2 semanas conforme sítio e bula; sem melhora, confirmar diagnóstico.'],
 adapalene:['Aplicar fina camada à noite na área acneica, começando em noites alternadas se irritar.','Reavaliar em 8–12 semanas; manutenção conforme resposta/tolerância.'],
 benzoyl:['Aplicar camada fina 1 vez/dia; reduzir frequência se irritação.','Reavaliar em 8–12 semanas; continuidade depende do controle e tolerância.']
 };
 const scheme=topical[id];if(!scheme){r.blocked.push('Esquema não cadastrado.');return r;}
 r.dose=scheme[0];r.use='Uso cutâneo. Lavar as mãos após aplicação (exceto se forem o local tratado).';r.duration=scheme[1];return r;
}

export type BaseSolution = {
  id: string;
  name: string;
  short: string;
  glucoseMgMl: number;
  na: number;
  k: number;
  cl: number;
  osm: number;
  note: string;
};

export const baseSolutions: BaseSolution[] = [
  { id: "sg5", name: "Soro glicosado 5%", short: "SG 5%", glucoseMgMl: 50, na: 0, k: 0, cl: 0, osm: 278, note: "Isosmolar na bolsa, fisiologicamente hipotônico após metabolização da glicose." },
  { id: "sg10", name: "Soro glicosado 10%", short: "SG 10%", glucoseMgMl: 100, na: 0, k: 0, cl: 0, osm: 555, note: "Hiperosmolar; não fornece sódio." },
  { id: "sf09", name: "Cloreto de sódio 0,9%", short: "SF 0,9%", glucoseMgMl: 0, na: 154, k: 0, cl: 154, osm: 308, note: "Isotônica, não balanceada; contabilizar carga de cloreto." },
