export const calculateForPresentation = (
  item: ClinicalItem,
  weight: number,
  selectedIndex = 0,
  selectedDoseVariant?: number,
): CalculationLine[] => {
  if (typeof weight !== "number" || !Number.isFinite(weight) || weight <= 0) return [];
  const lines = item.doseVariants
    ? typeof selectedDoseVariant === "number" && item.doseVariants[selectedDoseVariant]
      ? item.doseVariants[selectedDoseVariant].calculate(weight)
      : []
    : item.calculate(weight);
  const options = presentationOptions[item.id];
  if (!options) return lines;
  const selected = options[selectedIndex];
  if (!selected) return [];

  return lines.map((line) => {
    // As opções representam a apresentação do frasco/ampola. A vazão de uma
    // solução final de infusão só pode mudar após novo preparo explícito.
    if (selected.compatibleLineLabels?.length
      && !selected.compatibleLineLabels.some((label) => line.label.toLocaleLowerCase("pt-BR").includes(label.toLocaleLowerCase("pt-BR")))) {
      return {
        ...line,
        volume: undefined,
        volumeContext: `Conversão bloqueada: ${selected.label} não está validado nesta folha para a linha ${line.label}.`,
        preparedVolume: undefined,
        preparedVolumeContext: undefined,
        preparedReverse: undefined,
        reverse: `${line.dose}. Conversão para mL bloqueada: apresentação ${selected.label} incompatível com a linha ${line.label}.`,
      };
    }

    const result: CalculationLine = { ...line };

    const hasDose = Number.isFinite(line.doseAmount) && (line.doseAmount ?? -1) >= 0;
    const exactDose = line.doseAmount ?? 0;

    if (hasDose && selected.strength && selected.strengthUnit && selected.containerLabel) {
      const theoreticalUnits = exactDose / selected.strength;
      const containersToOpen = Math.max(1, Math.ceil(theoreticalUnits - Number.EPSILON));
      const displayedContainer = theoreticalUnits === 1
        ? selected.containerLabel
        : selected.containerLabel === "frasco-ampola"
          ? "frascos-ampola"
          : `${selected.containerLabel}s`;
      result.presentationQuantity = `${fmt(theoreticalUnits, 3)} ${displayedContainer} (abrir ${containersToOpen})`;
      result.presentationQuantityContext = "Quantidade teórica pela força do frasco; o volume a retirar depende da reconstituição específica da bula.";
      result.presentationQuantityReverse = `${fmt(theoreticalUnits, 6)} × ${fmt(selected.strength, 3)} ${selected.strengthUnit}/${selected.containerLabel} ≈ ${fmt(exactDose, 6)} ${selected.strengthUnit}`;
    }

    if (line.volumeConversionBlockedReason) {
      // A presentation choice is not confirmation of a drug identity or recipe.
      // Keep the clinical dose and reverse check; never restore blocked volumes.
      return {
        ...result,
        volume: undefined,
        volumeContext: `Conversão bloqueada: ${line.volumeConversionBlockedReason}`,
        preparedVolume: undefined,
        preparedVolumeContext: undefined,
        preparedReverse: undefined,
        stockPreparationVolume: undefined,
        stockPreparationContext: undefined,
        stockPreparationReverse: undefined,
        rate: undefined,
      };
    }

    if (selected.stockPreparation && selected.concentration && selected.unit) {
      const stockVolume = doseToVolume(selected.stockPreparation.amount, selected.concentration);
      if (stockVolume === null) return { label: line.label, dose: line.dose, reverse: "Preparo bloqueado: grandeza inválida." };
      result.stockPreparationVolume = `${fmt(stockVolume, 3)} mL`;
      result.stockPreparationContext = `Aspirar para preparar ${fmt(selected.stockPreparation.finalVolume, 3)} mL a ${selected.stockPreparation.finalConcentrationLabel}`;
      result.stockPreparationReverse = `${fmt(stockVolume, 6)} mL × ${fmt(selected.concentration, 6)} ${selected.unit} ≈ ${fmt(selected.stockPreparation.amount, 6)} ${selected.stockPreparation.amountUnit}; completar para ${fmt(selected.stockPreparation.finalVolume, 3)} mL → ${selected.stockPreparation.finalConcentrationLabel}`;
    }

    if (!hasDose) return result;

    if (selectedIndex === 0 && line.volume) return result;
    if (!selected.concentration || !selected.unit || (line.rate && !line.volume)) return result;

    const adjusted = doseToVolume(exactDose, selected.concentration);
    if (adjusted === null) return { label: line.label, dose: line.dose, reverse: "Conversão bloqueada: grandeza inválida." };
    const adjustedText = `${fmt(adjusted, 3)} mL`;
    const preparedConcentration = selected.preparedConcentration;
    const preparedVolume = typeof preparedConcentration === "number" && preparedConcentration > 0
      ? doseToVolume(exactDose, preparedConcentration)
      : undefined;
    if (preparedVolume === null) return { label: line.label, dose: line.dose, reverse: "Diluição bloqueada: grandeza inválida." };
    const preparedContext = selected.preparedLabel
      ?? `na concentração final de ${fmt(preparedConcentration ?? 0, 3)} ${selected.unit}`;
    const doseUnit = selected.unit.replace(/\/mL$/u, "");
    result.volume = adjustedText;
    result.volumeContext = `Aspirar da apresentação selecionada: ${selected.label}`;
    result.preparedVolume = preparedVolume === undefined ? undefined : `${fmt(preparedVolume, 3)} mL`;
    result.preparedVolumeContext = preparedVolume === undefined ? undefined : `Administrar ${preparedContext}`;
    result.preparedReverse = line.preparedReverse && line.rate ? line.preparedReverse : preparedVolume === undefined
      ? undefined
      : `${fmt(exactDose, 6)} ${doseUnit} ÷ ${fmt(preparedConcentration ?? 0, 3)} ${selected.unit} ≈ ${fmt(preparedVolume, 6)} mL; volume exibido ≈ ${fmt(preparedVolume, 3)} mL`;
    result.reverse = `${fmt(exactDose, 6)} ${doseUnit} ÷ ${fmt(selected.concentration, 6)} ${selected.unit} ≈ ${fmt(adjusted, 6)} mL; volume exibido ≈ ${adjustedText} (apresentação: ${selected.label})`;
    return result;
  });
};


