const fmt = (value: number, digits = 2) =>
  new Intl.NumberFormat("pt-BR", {
    maximumFractionDigits: digits,
    minimumFractionDigits: 0,
  }).format(value);

const cappedDose = (weight: number, perKg: number, max?: number, min?: number) => {
  let dose = weight * perKg;
  if (typeof max === "number") dose = Math.min(dose, max);
  if (typeof min === "number") dose = Math.max(dose, min);
  return dose;
};

const bolus = ({
  weight,
  points,
  concentration,
  doseUnit,
  preparedConcentration,
  preparedLabel,
  max,
  min,
}: {
  weight: number;
  points: Array<{ label: string; perKg: number; max?: number; min?: number }>;
  concentration: number;
  doseUnit: string;
  preparedConcentration?: number;
  preparedLabel?: string;
  max?: number;
  min?: number;
}): CalculationLine[] =>
  points.flatMap((point) => {
    const dose = cappedDose(weight, point.perKg, point.max ?? max, point.min ?? min);
    const volume = doseToVolume(dose, concentration);
    const preparedVolume = preparedConcentration ? doseToVolume(dose, preparedConcentration) : undefined;
    if (volume === null || preparedVolume === null) return [];
    const preparedContext = preparedLabel
      ?? `na concentração final de ${fmt(preparedConcentration ?? 0, 3)} ${doseUnit}/mL`;
    return [{
      label: point.label,
      dose: `${fmt(dose, 3)} ${doseUnit}`,
      doseAmount: dose,
      volume: `${fmt(volume, 3)} mL`,
      volumeContext: "Volume a aspirar da apresentação indicada",
      preparedVolume: preparedVolume === undefined ? undefined : `${fmt(preparedVolume, 3)} mL`,
      preparedVolumeContext: preparedVolume === undefined
        ? undefined
        : `Volume a administrar ${preparedContext}`,
      preparedReverse: preparedVolume === undefined
        ? undefined
        : `${fmt(preparedVolume, 6)} mL × ${fmt(preparedConcentration ?? 0, 3)} ${doseUnit}/mL ≈ ${fmt(dose, 6)} ${doseUnit}; volume exibido ≈ ${fmt(preparedVolume, 3)} mL`,
      reverse: `${fmt(dose, 6)} ${doseUnit} ÷ ${fmt(concentration, 6)} ${doseUnit}/mL ≈ ${fmt(volume, 6)} mL; volume exibido ≈ ${fmt(volume, 3)} mL (${fmt(dose / weight, 6)} ${doseUnit}/kg)`,
    }];
  });

const doseOnlyBolus = ({
  weight,
  points,
  doseUnit,
  blockedReason,
}: {
  weight: number;
  points: Array<{ label: string; perKg: number; max?: number; min?: number }>;
  doseUnit: string;
  blockedReason: string;
}): CalculationLine[] =>
  points.map((point) => {
    const dose = cappedDose(weight, point.perKg, point.max, point.min);
    const effectivePerKg = dose / weight;
    return {
      label: point.label,
      dose: `${fmt(dose, 3)} ${doseUnit}`,
      doseAmount: dose,
      volumeConversionBlockedReason: blockedReason,
      reverse: `${fmt(dose, 6)} ${doseUnit} ÷ ${fmt(weight, 6)} kg ≈ ${fmt(effectivePerKg, 6)} ${doseUnit}/kg. Conversão para mL bloqueada: ${blockedReason}`,
    };
  });

const infusion = ({
  weight,
  points,
  concentration,
  doseUnit,
  perMinute,
}: {
  weight: number;
  points: Array<{ label: string; perKg: number }>;
  concentration: number;
  doseUnit: ClinicalUnit;
  perMinute?: boolean;
}): CalculationLine[] =>
  points.flatMap((point) => {
    const calculated = calculateInfusion({ dosePerKg: point.perKg, weightKg: weight, doseUnit, period: perMinute ? "minute" : "hour", concentrationPerMl: concentration, concentrationUnit: doseUnit });
    if (calculated === null) return [];
    const rate = calculated.mlPerHour;
    const time = perMinute ? "min" : "h";
    return [{
      label: point.label,
      dose: `${fmt(point.perKg, 4)} ${doseUnit}/kg/${time}`,
      rate: `${fmt(rate, 3)} mL/h`,
      reverse: `${fmt(rate, 6)} mL/h × ${fmt(concentration, 6)} ${doseUnit}/mL${perMinute ? " ÷ 60" : ""} ÷ ${fmt(weight, 6)} kg ≈ ${fmt(point.perKg, 6)} ${doseUnit}/kg/${time}; vazão exibida ≈ ${fmt(rate, 3)} mL/h`,
    }];
  });

