// Dose e concentração em mmol de cálcio elementar, jamais em massa nominal do sal.
const calciumEmergency = (weight: number, scenario: "hypocalcemia" | "hyperkalemia-stable" | "hyperkalemia-unstable"): CalculationLine[] => {
  const hypocalcemia = scenario === "hypocalcemia";
  const dose = Math.min(weight * (hypocalcemia ? 0.11 : 0.15), hypocalcemia ? 4.4 : 6.6);
  const stockVolume = dose / 0.2325;
  const finalConcentration = hypocalcemia ? 0.044 : 0.2325;
  const finalVolume = dose / finalConcentration;
  const minutes = hypocalcemia ? 10 : scenario === "hyperkalemia-stable" ? 20 : Math.ceil(Math.max(5, stockVolume / 5));
  const rate = Math.floor(finalVolume * 60 / minutes * 1000) / 1000;
  return [{ label: hypocalcemia ? "Hipocalcemia" : "Hipercalemia com alteração no ECG", dose: `${fmt(dose, 4)} mmol de cálcio elementar`, doseAmount: dose,
    volume: `${fmt(stockVolume, 4)} mL`, volumeContext: "Aspirar exclusivamente do produto a 0,2325 mmol de Ca/mL",
    preparedVolume: `${fmt(finalVolume, 4)} mL`, preparedVolumeContext: hypocalcemia ? `Adicionar ${fmt(finalVolume - stockVolume, 4)} mL de diluente: concentração final 0,044 mmol/mL` : "Solução a 0,2325 mmol/mL; confirmar acesso seguro para esta técnica",
    rate: `${fmt(rate, 3)} mL/h por pelo menos ${minutes} min; programar o volume final total`,
    preparedReverse: `${fmt(finalVolume, 6)} mL × ${fmt(finalConcentration, 4)} mmol/mL ≈ ${fmt(dose, 6)} mmol; bomba arredondada para baixo, duração mínima ${minutes} min`,
    reverse: `${fmt(stockVolume, 6)} mL × 0,2325 mmol/mL ≈ ${fmt(dose, 6)} mmol ≈ ${fmt(dose * 2, 6)} mEq; ${fmt(stockVolume / minutes, 6)} mL/min de produto (≤5)` }];
};

