export const quickCalculations = (weight: number, ageMonths?: number) => {
  const hollidaySegarDay = weight <= 10
    ? weight * 100
    : weight <= 20
      ? 1000 + (weight - 10) * 50
      : 1500 + (weight - 20) * 20;
  const maintenanceDay = Math.min(hollidaySegarDay, 2400);
  const firstShock = weight * 2;
  const secondShock = weight * 4;
  const neonatalMaintenanceBlocked = ageMonths === undefined;
  return [
    {
      label: "Desfibrilação",
      value: `${fmt(firstShock)} J → ${fmt(secondShock)} J`,
      note: "Primeiro choque: 2 J/kg. Segundo: 4 J/kg. Subsequentes: ≥4 J/kg; máximo 10 J/kg ou dose adulta, o menor.",
    },
    {
      label: "Cardioversão sincronizada",
      value: `${fmt(weight * 0.5)}–${fmt(weight)} J`,
      note: `Se ineficaz: ${fmt(weight * 2)} J`,
    },
    {
      label: "Cristaloide",
      value: `${fmt(weight * 10)}–${fmt(weight * 20)} mL`,
      note: "Reavaliar após cada alíquota",
    },
    {
      label: "Manutenção basal",
      value: (ageMonths !== undefined && ageMonths < 1) || neonatalMaintenanceBlocked
        ? "Protocolo neonatal obrigatório"
        : `${fmt(maintenanceDay / 24)} mL/h`,
      note: (ageMonths !== undefined && ageMonths < 1) || neonatalMaintenanceBlocked
        ? "Não aplicar Holliday–Segar isoladamente quando o contexto neonatal não foi excluído; informar idade e, se neonato, definir dia de vida, idade gestacional, diurese, eletrólitos, demais aportes e protocolo neonatal."
        : `${fmt(maintenanceDay)} mL/dia por Holliday–Segar; teto desta referência: 2.400 mL/dia (100 mL/h). Ajustar à diurese, ao quadro e ao risco de sobrecarga`,
    },
  ];
};

export const equipmentEstimates = (weight: number, ageMonths?: number) => {
  const ageYears = typeof ageMonths === "number" ? ageMonths / 12 : undefined;
  const roundToHalf = (value: number) => Math.round(value * 2) / 2;
  const ettByWeight = weight < 2 ? 2.5 : weight < 4 ? 3 : weight < 8 ? 3.5 : weight < 15 ? 4 : weight < 20 ? 4.5 : weight < 30 ? 5 : weight < 40 ? 5.5 : weight < 50 ? 6 : weight < 60 ? 6.5 : weight < 75 ? 7 : 7.5;
  const ettCuffed = ageYears !== undefined && ageYears >= 1 ? roundToHalf(Math.min(8, ageYears / 4 + 3.5)) : ettByWeight;
  const ettUncuffed = ageYears !== undefined && ageYears >= 1 ? roundToHalf(ageYears / 4 + 4) : ettCuffed + 0.5;
  const depth = ageYears !== undefined && ageYears >= 1 ? ageYears / 2 + 12 : ettCuffed * 3;
  const blade = weight < 1.5 ? "00–0 reta" : weight < 4 ? "0 reta" : weight < 10 ? "1 reta" : weight < 25 ? "2 reta/curva" : "2–3 curva";
  const suction = weight < 5 ? "6–8 Fr" : weight < 15 ? "8–10 Fr" : weight < 30 ? "10–12 Fr" : "12–14 Fr";
  const supraglottic = weight < 5 ? "nº 1" : weight < 10 ? "nº 1,5" : weight < 20 ? "nº 2" : weight < 30 ? "nº 2,5" : weight < 50 ? "nº 3" : weight < 70 ? "nº 4" : "nº 5";
  const peripheral = weight < 5 ? "24–22 G" : weight < 15 ? "22–20 G" : weight < 30 ? "20–18 G" : "18–16 G";
  const cvc = weight < 5 ? "3 Fr / 22 G" : weight < 15 ? "4 Fr / 20–22 G" : weight < 30 ? "5 Fr / 18–20 G" : "6 Fr / 16–18 G";
  const chestTube = weight < 5 ? "8–12 Fr" : weight < 10 ? "10–16 Fr" : weight < 20 ? "16–20 Fr" : weight < 40 ? "20–28 Fr" : "28–32 Fr";
  const urinary = weight < 5 ? "6 Fr" : weight < 15 ? "8 Fr" : weight < 30 ? "10 Fr" : weight < 50 ? "12 Fr" : "14 Fr";
  const decompression = weight < 10 ? "18–20 G" : weight < 25 ? "16–18 G" : "14–16 G";
  return [
    { label: "Tubo com cuff", value: `${fmt(ettCuffed, 1)} mm`, note: "Arredondado a 0,5 mm; ter um menor e um maior" },
    { label: "Tubo sem cuff", value: `${fmt(ettUncuffed, 1)} mm`, note: "Arredondado a 0,5 mm; confirmar clinicamente" },
    { label: "Profundidade oral", value: `${fmt(depth, 1)} cm`, note: "Confirmar capnografia e imagem" },
    { label: "Lâmina", value: blade, note: "Confirmar anatomia e dispositivo" },
    { label: "Aspiração", value: suction, note: "Estimativa por peso" },
    { label: "Supraglótico", value: supraglottic, note: "Confirmar tabela do fabricante" },
    { label: "Acesso periférico", value: peripheral, note: "Escolher maior calibre viável" },
    { label: "CVC estimado", value: cvc, note: "Sítio e comprimento por ultrassom" },
    { label: "Dreno torácico", value: chestTube, note: "Ajustar à indicação e técnica" },
    { label: "Descompressão", value: decompression, note: "Comprimento é tão importante quanto calibre" },
    { label: "Sonda vesical", value: urinary, note: "Estimativa; evitar se sem indicação" },
  ];
};

