export const pressureHierarchyErrors = ({
  peak,
  plateau,
  totalPeep,
  setPeep,
}: {
  peak: number;
  plateau: number;
  totalPeep: number;
  setPeep: number;
}): string[] => {
  const errors: string[] = [];
  if (Number.isFinite(peak) && Number.isFinite(plateau) && peak < plateau) errors.push("Ppico deve ser ≥ Pplat");
  if (Number.isFinite(plateau) && Number.isFinite(totalPeep) && plateau < totalPeep) errors.push("Pplat deve ser ≥ PEEP total");
  if (Number.isFinite(totalPeep) && Number.isFinite(setPeep) && totalPeep < setPeep) errors.push("PEEP total deve ser ≥ PEEP ajustada");
  return errors;
};

export const protectedReferenceWeight = ({
  population,
  measuredWeight,
  adultPbw,
  confirmedPards,
  pediatricPbw,
  neonatalContextReady,
}: {
  population: "adulto" | "pediatria" | "neonatal";
  measuredWeight: number;
  adultPbw: number;
  confirmedPards: boolean;
  pediatricPbw: number;
  neonatalContextReady: boolean;
}) => {
  if (population === "adulto") return Number.isFinite(adultPbw) && adultPbw > 0 ? adultPbw : Number.NaN;
  if (population === "neonatal") return neonatalContextReady && measuredWeight >= 0.3 && measuredWeight <= 15 ? measuredWeight : Number.NaN;
  if (confirmedPards) {
    if (!(measuredWeight > 0) || !(Number.isFinite(pediatricPbw) && pediatricPbw > 0)) return Number.NaN;
    return Math.min(measuredWeight, pediatricPbw);
  }
  return measuredWeight > 0 ? measuredWeight : Number.NaN;
};

export const populationHeight = (population: "adulto" | "pediatria" | "neonatal", height: number): number => {
  const minimum = population === "adulto" ? 120 : 30;
  const maximum = population === "adulto" ? 230 : 220;
  return Number.isFinite(height) && height >= minimum && height <= maximum ? height : Number.NaN;
};

export const validNeonatalContext = ({ ageYears, gestationalWeeks }: { ageYears: number; gestationalWeeks: number }): boolean => {
  const postmenstrualWeeks = gestationalWeeks + ageYears * 52.1775;
  return Number.isFinite(ageYears)
    && ageYears >= 0
    && ageYears <= 1
    && Number.isFinite(gestationalWeeks)
    && gestationalWeeks >= 22
    && gestationalWeeks < 45
    && postmenstrualWeeks <= 64;
};

export const postmenstrualAgeWeeks = ({ ageYears, gestationalWeeks }: { ageYears: number; gestationalWeeks: number }): number =>
  validNeonatalContext({ ageYears, gestationalWeeks }) ? gestationalWeeks + ageYears * 52.1775 : Number.NaN;

export const adultEcmoEarlyConsult = ({
  invasive, ardsContext, optimized, refractory, proneCompletedOrContraindicated, pf, ph, paco2, criterionHours,
  fio2, setPeep, plateau, totalRate,
}: {
  invasive: boolean; ardsContext: boolean; optimized: boolean; refractory: boolean; proneCompletedOrContraindicated: boolean;
  pf: number; ph: number; paco2: number; criterionHours: number; fio2: number; setPeep: number; plateau: number; totalRate: number;
}): boolean => {
  if (!invasive || !ardsContext || !optimized || !refractory || !proneCompletedOrContraindicated || !Number.isFinite(criterionHours)) return false;
  const optimizedHypoxemia = Number.isFinite(fio2) && fio2 >= 0.8 && Number.isFinite(setPeep) && setPeep >= 10;
  const hypoxemicCriterion = optimizedHypoxemia && (
    (pf > 0 && pf < 50 && criterionHours >= 3)
    || (pf > 0 && pf < 80 && criterionHours >= 6)
  );
  const hypercapnicCriterion = ph < 7.25
    && paco2 >= 60
    && criterionHours >= 6
    && Number.isFinite(totalRate)
    && totalRate >= 35
    && Number.isFinite(plateau)
    && plateau > 0
    && plateau <= 32;
  return hypoxemicCriterion || hypercapnicCriterion;
};

export const pressureAlarmLabel = ({ validHierarchy, peak, neonatal }: { validHierarchy: boolean; peak: number; neonatal: boolean }): string => {
  if (!validHierarchy) return "indisponível — corrija a hierarquia de pressões";
  return Number.isFinite(peak) && peak > 0 ? `${Math.round(peak + (neonatal ? 3 : 5))} cmH₂O (referência inicial)` : "Ppico basal + 3–5 cmH₂O";
};

export const pressureDependentAlarmLabels = ({
  validHierarchy,
  setPeep,
  plateau,
  population,
  pards,
}: {
  validHierarchy: boolean;
  setPeep: number;
  plateau: number;
  population: "adulto" | "pediatria" | "neonatal";
  pards: boolean;
}): { peepLow: string; plateauAlert: string } => {
  const unavailable = "indisponível — corrija a hierarquia de pressões";
  if (!validHierarchy) return { peepLow: unavailable, plateauAlert: unavailable };
  const peepLow = Number.isFinite(setPeep) && setPeep > 0 ? `${Math.max(0, setPeep - 2)} cmH₂O` : "PEEP ajustada −2";
  const plateauAlert = Number.isFinite(plateau) && plateau > 0
    ? `${population === "adulto" ? "<30" : population === "pediatria" && pards ? "≤28 (PARDS)" : "sem corte universal"} cmH₂O; atual ${plateau}`
    : population === "neonatal" ? "não extrapolar limite adulto/PARDS" : "medir por pausa inspiratória";
  return { peepLow, plateauAlert };
};
